  // Test cases
  assert(fixSpaces("Example") == "Example");
  assert(fixSpaces("Example 1") == "Example_1");
  assert(fixSpaces(" Example 2") == "_Example_2");
  assert(fixSpaces(" Example   3") == "_Example-3");

  print("All tests passed!");
}

